import { reduxForm } from "redux-form";
import { createField, Input } from "../../Common/FormsControl/FormsControl";
import { required } from "../../Utils/Validators/Validators";
import { connect } from "react-redux";
import { login } from "../../Redax/auth-reducer";
import { Navigate } from "react-router-dom";
import style from "./../../Common/FormsControl/FormsControl.module.css"

const LoginForm = ({ handleSubmit, error }) => {
    return (
        <form onSubmit={handleSubmit}>
            {createField("Email", "email", [required], Input)}
            {createField("Password", "password", [required], Input, { type: "password" })}
            {createField("Remember me", "rememberMe", [], Input, { type: "checkbox" })}
            {error && <div className={style.formSummaryError}>{error}
            </div>}
            <div>
                <button>Login</button>
            </div>
        </form>
    );
}

const LoginReduxForm = reduxForm({ form: 'login' })(LoginForm)

const Login = (props) => {
    const onSubmit = (formData) => {
        props.login(formData.email, formData.password, formData.rememberMe);
    }

    if (props.isAuth) {
        return <Navigate to={"/profile"} />
    }

    return <div>
        <h1>S.E.N. $ Login $ S.E.N. </h1>
        <LoginReduxForm onSubmit={onSubmit} />
    </div>
}

const maoStateToProps = (state) => ({
    isAuth: state.auth.isAuth
})

export default connect(maoStateToProps, { login })(Login);